    const base = count.map(c => c.reduce((a, b) => a + b, 0)), keep = marks.map((_, k) => k).filter(k => base[k] >= 8);
    const data = {}; S_STATES.forEach((s, i) => { data[s] = keep.map(k => 100 * count[k][i] / base[k]); });
